// src/handlers/pty-socket.ts
import { Effect, Queue } from "effect";
import { Socket } from "effect/socket";
function runPtySocket2(input) {
  const drain = Effect.gen(function* () {
    const writer = yield* input.socket.writer;
    while (true) {
      const item = yield* Queue.take(input.outbox);
      yield* writer.write(item);
      if (item instanceof Socket.CloseEvent)
        return;
    }
  });
  const read = Effect.gen(function* () {
    const reader = yield* input.socket.reader;
    if (input.onOpen)
      yield* input.onOpen;
    while (true)
      yield* Effect.forEach(yield* reader.pull, input.onMessage, { discard: true });
  });
  return Effect.raceFirst(drain, read).pipe(Effect.ensuring(Effect.sync(input.detach)), Effect.catchReason("SocketError", "SocketCloseError", () => Effect.void), Effect.orDie);
}

export { runPtySocket2 };
